class Node:
    def __init__(self, val, next=None):
        self.val, self.next = val, next
def show(node):
    return f"{node.val} -> {show(node.next)}" if node else "None"
def reverse(head):
    prev = None
    while head:
        nxt = head.next      # remember the rest
        head.next = prev     # flip this arrow
        prev, head = head, nxt
    return prev
head = Node(1, Node(2, Node(3, Node(4))))
print(show(head))
print(show(reverse(head)))
